VALUES ('hintek-riskbedomning', 'Riskbedömning', '', 'Risker med sannolikhet och konsekvens före och efter skyddsåtgärd, riskmatris, gemensamma åtgärder och godkännande.', 'HINTEK:s original, byggt av formulärskaparens byggstenar. Publiceras vid övergången från den inbyggda typen.', 'amber', 'shield-check', 'SAFETY', true, true, 'DRAFT', '{"schema":2,"blocks":[{"id":"risk-stod","type":"section","title":"Bedömningsstöd","description":"Femgradig skala och riskmatris. Samma skala används före och efter skyddsåtgärderna.","newPage":false,"blocks":[{"id":"risk-n-sannolikhet","type":"note","title":"Sannolikhet","text":"1 – Mycket osannolik\n2 – Osannolik\n3 – Möjlig\n4 – Sannolik\n5 – Mycket sannolik","visibility":{"task":true,"pdf":false}},{"id":"risk-n-konsekvens","type":"note","title":"Konsekvens","text":"1 – Försumbar\n2 – Mindre\n3 – Allvarlig\n4 – Mycket allvarlig\n5 – Katastrofal","visibility":{"task":true,"pdf":false}},{"id":"risk-n-sa","type":"note","title":"Så bedöms risken","text":"Multiplicera sannolikhet med konsekvens. Dokumentera sedan en konkret skyddsåtgärd och bedöm den kvarvarande risken på nytt. Mycket hög eller hög kvarvarande risk bör åtgärdas innan arbetet startar.","visibility":{"task":true,"pdf":false}},{"id":"risk-matris","type":"matrix","label":"Riskmatris 5 × 5","size":5,"xLabel":"Sannolikhet","yLabel":"Konsekvens","bands":[{"from":1,"label":"Låg","tone":"success"},{"from":5,"label":"Måttlig","tone":"warning"},{"from":10,"label":"Hög","tone":"danger"},{"from":17,"label":"Mycket hög","tone":"critical"}],"visibility":{"task":true,"pdf":true}}],"optional":false,"defaultOn":true,"pdfStyle":"standard","collapsed":true},{"id":"risk-risker","type":"section","title":"Identifierade risker","description":"Beskriv faran och skyddsåtgärden och bedöm risken före och efter åtgärden.","newPage":false,"blocks":[{"id":"risk-t-risker","type":"table","key":"risker","label":"Identifierade risker","columns":[{"id":"risk-c-fara","key":"fara","label":"Risk eller fara